//! Shared helpers for integration tests.

use std::path::PathBuf;

/// A golden fixture directory (`replies` or `control`): the canonical one in
/// `protocol/fixtures/`, generated by the Swift implementation, when the
/// repository has it, otherwise this crate's samples in `tests/fixtures/`.
/// `PLANMETER_FIXTURES=dir` forces `dir/<sub>`.
pub fn fixture_dir(sub: &str) -> PathBuf {
    if let Some(dir) = std::env::var_os("PLANMETER_FIXTURES") {
        return PathBuf::from(dir).join(sub);
    }
    let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let canonical = manifest.join("../protocol/fixtures").join(sub);
    if canonical.is_dir() {
        return canonical;
    }
    manifest.join("tests/fixtures").join(sub)
}

/// JSON files in a fixture subdirectory, sorted by name.
pub fn json_files(sub: &str) -> Vec<PathBuf> {
    let dir = fixture_dir(sub);
    let mut files: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", dir.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|x| x == "json"))
        .collect();
    files.sort();
    files
}

pub fn stem(path: &std::path::Path) -> String {
    path.file_stem()
        .unwrap_or_default()
        .to_string_lossy()
        .into_owned()
}
